    strcpy(cookbook[recipe_count].ingredients[1].amount, "2 tbsp");
    strcpy(cookbook[recipe_count].ingredients[2].name, "Butter");
    strcpy(cookbook[recipe_count].ingredients[2].amount, "1 tsp");
    recipe_count++;

    // Recipe 2: Simple Pasta
